/**
 * Minimal example of calling asset-token through the TypeScript bindings
 * generated by `stellar contract bindings typescript`.
 *
 * Generate the client first (`npm run generate`) and copy `.env.example` to
 * `.env`. See README.md for the full walkthrough.
 */
import { Keypair } from "@stellar/stellar-sdk";
import { Client } from "../bindings/src/index.js";

const contractId = requireEnv("CONTRACT_ID");
const rpcUrl = requireEnv("RPC_URL");
const networkPassphrase = requireEnv("NETWORK_PASSPHRASE");
const admin = Keypair.fromSecret(requireEnv("ADMIN_SECRET"));

// The recipient must also be allowlisted on the compliance contract before
// the transfer will succeed. On a local network, reuse the funded admin
// identity if you have not approved a second address yet.
const recipient = Keypair.random().publicKey();

const client = new Client({
  contractId,
  rpcUrl,
  networkPassphrase,
  publicKey: admin.publicKey(),
  signTransaction: async (tx) => {
    tx.sign(admin);
    return tx;
  },
});

async function main() {
  const adminBefore = await client.balance({ address: admin.publicKey() });
  const recipientBefore = await client.balance({ address: recipient });
  console.log("admin balance before:", adminBefore.result);
  console.log("recipient balance before:", recipientBefore.result);

  await client.transfer({
    from: admin.publicKey(),
    to: recipient,
    amount: 100n,
  });

  const adminAfter = await client.balance({ address: admin.publicKey() });
  const recipientAfter = await client.balance({ address: recipient });
  console.log("admin balance after:", adminAfter.result);
  console.log("recipient balance after:", recipientAfter.result);
}

function requireEnv(name: string): string {
  const value = process.env[name];
  if (!value) throw new Error(`Missing ${name}; copy .env.example to .env`);
  return value;
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});
